$eventName = $searchData['event_name'] ?? null;
if (StringUtil::isNotBlank($eventName)) {
    $qb->andWhere('e.nameJp LIKE :eventName OR e.nameEn LIKE :eventName')
        ->setParameter('eventName', '%'.trim($eventName).'%');
}

$baseInfos = array_values(array_filter((array) ($searchData['base_info'] ?? [])));
if ($baseInfos !== []) {
    $baseInfoIds = array_values(array_unique(array_map(fn (BaseInfo $baseInfo) => $baseInfo->getId(), $baseInfos)));
    $qb->andWhere('IDENTITY(e.BaseInfo) IN (:baseInfoIds)')
        ->setParameter('baseInfoIds', $baseInfoIds);
}

